-- Seed SSI-oriented templates + two packets. PDF keys empty until files uploaded to R2.
-- Legal display text is abbreviated placeholders until PDFs are ingested (do not rewrite SSI legal text in production — paste from PDF).

INSERT OR REPLACE INTO form_templates (id, key, name, version, status, schema_json, pdf_r2_key, pdf_mode, pdf_mapping_json, languages, retention_days, valid_days, created_at, updated_at) VALUES
(1, 'try_scuba_reg', 'Try Scuba Registration', '1', 'active',
 '{"key":"try_scuba_reg","consent":{"required":true,"version":"ssi-reg-v1","text":{"en":"I agree that the information on this registration is true and I accept responsibility for the content of this page.","es":"Acepto que la información de este registro es verdadera y asumo la responsabilidad del contenido de esta página."}},"sections":[{"id":"about","title":{"en":"About you","es":"Sobre ti"},"fields":[{"key":"first_name","type":"text","required":true,"source":"first_name","label":{"en":"First name","es":"Nombre"}},{"key":"last_name","type":"text","required":true,"source":"last_name","label":{"en":"Last name","es":"Apellido"}},{"key":"dob","type":"dob","required":true,"source":"dob","label":{"en":"Date of birth","es":"Fecha de nacimiento"}},{"key":"email","type":"email","source":"email","label":{"en":"Email","es":"Correo"}},{"key":"cell_phone","type":"phone","required":true,"source":"cell_phone","label":{"en":"Mobile phone","es":"Celular"}},{"key":"address","type":"address","source":"address","label":{"en":"Address","es":"Dirección"}}]},{"id":"emergency","title":{"en":"Emergency contact","es":"Contacto de emergencia"},"fields":[{"key":"emergency_contact_name","type":"text","required":true,"source":"emergency_contact_name","label":{"en":"Name","es":"Nombre"}},{"key":"emergency_contact_relationship","type":"text","source":"emergency_contact_relationship","label":{"en":"Relationship","es":"Relación"}},{"key":"emergency_contact_phone","type":"phone","required":true,"source":"emergency_contact_phone","label":{"en":"Phone","es":"Teléfono"}}]},{"id":"guardian","title":{"en":"Guardian (under 18)","es":"Tutor (menor de 18)"},"show_if":{"op":"age_lt","value":18},"fields":[{"key":"guardian_name","type":"text","required":true,"label":{"en":"Guardian full name","es":"Nombre del tutor"}},{"key":"__guardian_signed","type":"checkbox","required":true,"label":{"en":"Guardian has signed","es":"El tutor ha firmado"}}]},{"id":"ack","title":{"en":"Acknowledgement","es":"Reconocimiento"},"fields":[{"key":"page_ack","type":"checkbox","required":true,"label":{"en":"By placing my name here, I agree to be responsible for the content of this page","es":"Al colocar mi nombre aquí, acepto ser responsable del contenido de esta página"}}]}]}',
 '', 'overlay', '{"placements":[]}','["en","es"]', 2555, NULL, strftime('%s','now')*1000, strftime('%s','now')*1000),

(2, 'intro_code', 'Introductory Scuba Code', '1', 'active',
 '{"key":"intro_code","consent":{"required":true,"version":"ssi-intro-code-v1","text":{"en":"[Paste SSI Introductory Scuba Code waiver text from PDF — do not rewrite.]","es":"[Pegar texto SSI del PDF — no reescribir.]"}},"sections":[{"id":"code","title":{"en":"Code of conduct","es":"Código"},"fields":[{"key":"intro_ack","type":"checkbox","required":true,"label":{"en":"I have read and agree to the Introductory Scuba Code","es":"He leído y acepto el Código de Buceo Introductorio"}},{"key":"not_pregnant_notice","type":"checkbox","required":true,"label":{"en":"I understand: do not dive if pregnant","es":"Entiendo: no bucear si está embarazada"}}]}]}',
 '', 'overlay', '{"placements":[]}','["en","es"]', 2555, NULL, strftime('%s','now')*1000, strftime('%s','now')*1000),

(3, 'fit_to_dive', 'Fit to Dive', '1', 'active',
 '{"key":"fit_to_dive","consent":{"required":true,"version":"ssi-fit-v1","text":{"en":"[Paste Fit to Dive medical questionnaire text from PDF.]","es":"[Pegar texto Fit to Dive del PDF.]"}},"sections":[{"id":"fit","title":{"en":"Medical questions","es":"Preguntas médicas"},"fields":[{"key":"fit_q1","type":"yes_no","required":true,"sensitive":true,"label":{"en":"Any heart or circulation problems?","es":"¿Problemas del corazón o circulación?"}},{"key":"fit_q1_detail","type":"textarea","sensitive":true,"show_if":{"field":"fit_q1","op":"eq","value":"yes"},"label":{"en":"Details","es":"Detalles"}},{"key":"fit_q2","type":"yes_no","required":true,"sensitive":true,"label":{"en":"Any lung or breathing problems?","es":"¿Problemas pulmonares o respiratorios?"}},{"key":"fit_q3","type":"yes_no","required":true,"sensitive":true,"label":{"en":"Any other medical condition that may affect diving?","es":"¿Otra condición médica que afecte el buceo?"}},{"key":"not_pregnant_notice","type":"checkbox","required":true,"label":{"en":"I understand: do not dive if pregnant","es":"Entiendo: no bucear si está embarazada"}}]}]}',
 '', 'overlay', '{"placements":[]}','["en","es"]', 2555, NULL, strftime('%s','now')*1000, strftime('%s','now')*1000),

(4, 'privacy', 'Privacy Policy', '1', 'active',
 '{"key":"privacy","consent":{"required":true,"version":"ssi-privacy-v1","text":{"en":"[Paste SSI Privacy Policy text from PDF.]","es":"[Pegar Política de Privacidad SSI del PDF.]"}},"sections":[{"id":"tc","title":{"en":"Training center","es":"Centro de entrenamiento"},"fields":[{"key":"training_center_name","type":"text","source":"training_center_name","label":{"en":"Training center name","es":"Nombre del centro"}},{"key":"training_center_address","type":"textarea","source":"training_center_address","label":{"en":"Training center address","es":"Dirección del centro"}}]},{"id":"g16","title":{"en":"Under 16 guardian consent","es":"Consentimiento del tutor (<16)"},"show_if":{"op":"age_lt","value":16},"fields":[{"key":"guardian_privacy_consent","type":"checkbox","required":true,"label":{"en":"Guardian consents to privacy terms","es":"El tutor acepta los términos de privacidad"}}]}]}',
 '', 'overlay', '{"placements":[]}','["en","es"]', 2555, NULL, strftime('%s','now')*1000, strftime('%s','now')*1000),

(5, 'rec_waiver', 'Recreational Waiver', '1', 'active',
 '{"key":"rec_waiver","consent":{"required":true,"version":"ssi-waiver-v1","text":{"en":"[Paste recreational waiver text from PDF.]","es":"[Pegar exención recreativa del PDF.]"}},"sections":[{"id":"w","title":{"en":"Waiver","es":"Exención"},"fields":[{"key":"waiver_ack","type":"checkbox","required":true,"label":{"en":"I have read and agree to this recreational diving waiver","es":"He leído y acepto esta exención de buceo recreativo"}},{"key":"not_pregnant_notice","type":"checkbox","required":true,"label":{"en":"I understand: do not dive if pregnant","es":"Entiendo: no bucear si está embarazada"}}]}]}',
 '', 'overlay', '{"placements":[]}','["en","es"]', 2555, 365, strftime('%s','now')*1000, strftime('%s','now')*1000),

(6, 'diver_medical', 'Diver Medical Participant Questionnaire', '1', 'active',
 '{"key":"diver_medical","consent":{"required":true,"version":"dm-v2","text":{"en":"Scuba needs good physical health. Answer honestly. If pregnant, do not dive. Yes on #3, #5, #10, or any follow-up box means a physician must clear you before diving.","es":"El buceo requiere buena salud física. Responde con honestidad. Si está embarazada, no bucee. Sí en #3, #5, #10 o cualquier casilla de seguimiento implica autorización médica antes de bucear."}},"sections":[{"id":"dm","title":{"en":"Medical questionnaire","es":"Cuestionario médico"},"fields":[{"key":"over_45","type":"yes_no","required":true,"label":{"en":"I am 45 years of age or older","es":"Tengo 45 años o más"}},{"key":"dm_q1","type":"yes_no","required":true,"sensitive":true,"label":{"en":"1. Problems with lungs, breathing, heart, blood, or a COVID-19 diagnosis?","es":"1. ¿Problemas de pulmones, respiración, corazón, sangre, o diagnóstico de COVID-19?"}},{"key":"dm_box_A","type":"yes_no","sensitive":true,"show_if":{"field":"dm_q1","op":"eq","value":"yes"},"label":{"en":"Box A — Chest/heart surgery or collapsed lung; asthma/allergies limiting exercise (past year); heart illness or heart meds; bronchitis/emphysema; COVID-19?","es":"Casilla A — Cirugía de pecho/corazón o pulmón colapsado; asma/alergias que limitan ejercicio (último año); enfermedad o medicación cardíaca; bronquitis/enfisema; COVID-19?"}},{"key":"dm_box_B","type":"yes_no","sensitive":true,"show_if":{"field":"over_45","op":"eq","value":"yes"},"label":{"en":"Box B (45+) — Smoke/nicotine; high cholesterol; high blood pressure; close relative died of heart disease or stroke before 50?","es":"Casilla B (45+) — ¿Fumo/nicotina; colesterol alto; presión alta; familiar cercano falleció por corazón o ACV antes de 50?"}},{"key":"dm_q3","type":"yes_no","required":true,"sensitive":true,"label":{"en":"3. Trouble with moderate exercise (e.g. walk 1 mile in 14 min, or swim 200 m without rest), or unable to do normal activity for fitness/health in the past 12 months? (physician if YES)","es":"3. ¿Te cuesta el ejercicio moderado (p. ej. caminar 1 milla en 14 min, o nadar 200 m sin descanso), o no pudiste hacer actividad normal por salud en 12 meses? (médico si SÍ)"}},{"key":"dm_q4","type":"yes_no","required":true,"sensitive":true,"label":{"en":"4. Problems with eyes, ears, or sinuses?","es":"4. ¿Problemas de ojos, oídos o senos nasales?"}},{"key":"dm_box_C","type":"yes_no","sensitive":true,"show_if":{"field":"dm_q4","op":"eq","value":"yes"},"label":{"en":"Box C — Sinus surgery (6 mo); ear disease/surgery, hearing loss, or balance issues; recurrent sinusitis (12 mo); eye surgery (3 mo)?","es":"Casilla C — Cirugía de senos (6 meses); oído, pérdida auditiva o equilibrio; sinusitis recurrente (12 meses); cirugía ocular (3 meses)?"}},{"key":"dm_q5","type":"yes_no","required":true,"sensitive":true,"label":{"en":"5. Surgery in the last 12 months, or ongoing issues from past surgery? (physician if YES)","es":"5. ¿Cirugía en los últimos 12 meses, o problemas persistentes de cirugías pasadas? (médico si SÍ)"}},{"key":"dm_q6","type":"yes_no","required":true,"sensitive":true,"label":{"en":"6. Loss of consciousness, migraines, seizures, stroke, serious head injury, or lasting neurologic disease?","es":"6. ¿Pérdida de conciencia, migrañas, convulsiones, ACV, lesión craneal grave, o enfermedad neurológica persistente?"}},{"key":"dm_box_D","type":"yes_no","sensitive":true,"show_if":{"field":"dm_q6","op":"eq","value":"yes"},"label":{"en":"Box D — Head injury with blackout (5 yr); lasting neurologic disease; recurring migraines (12 mo); fainting (5 yr); epilepsy/seizures or seizure meds?","es":"Casilla D — Traumatismo con desmayo (5 años); enfermedad neurológica; migrañas recurrentes (12 meses); desmayos (5 años); epilepsia/convulsiones o medicación?"}},{"key":"dm_q7","type":"yes_no","required":true,"sensitive":true,"label":{"en":"7. Treatment now (or in the last 5 years) for psychological issues, personality disorder, panic attacks, or addiction; or a diagnosed learning disability?","es":"7. ¿Tratamiento ahora (o en 5 años) por temas psicológicos, trastorno de personalidad, pánico o adicción; o discapacidad del aprendizaje diagnosticada?"}},{"key":"dm_box_E","type":"yes_no","sensitive":true,"show_if":{"field":"dm_q7","op":"eq","value":"yes"},"label":{"en":"Box E — Mental health care needed; major depression, suicidal thoughts, panic, or bipolar on treatment; learning/developmental disorder in ongoing care; addiction treatment in 5 years?","es":"Casilla E — Atención de salud mental; depresión mayor, ideas suicidas, pánico o bipolar en tratamiento; trastorno del aprendizaje con cuidado continuo; tratamiento por adicción en 5 años?"}},{"key":"dm_q8","type":"yes_no","required":true,"sensitive":true,"label":{"en":"8. Back problems, hernia, ulcers, or diabetes?","es":"8. ¿Problemas de espalda, hernia, úlceras o diabetes?"}},{"key":"dm_box_F","type":"yes_no","sensitive":true,"show_if":{"field":"dm_q8","op":"eq","value":"yes"},"label":{"en":"Box F — Recurring back pain limiting activity (6 mo); spine surgery (12 mo); diabetes or gestational diabetes (12 mo); hernia limiting activity; active ulcers or ulcer surgery (6 mo)?","es":"Casilla F — Dolor de espalda recurrente que limita (6 meses); cirugía de columna (12 meses); diabetes o gestacional (12 meses); hernia que limita; úlceras activas o cirugía (6 meses)?"}},{"key":"dm_q9","type":"yes_no","required":true,"sensitive":true,"label":{"en":"9. Stomach or intestine problems, including recent diarrhea?","es":"9. ¿Problemas de estómago o intestino, incluida diarrea reciente?"}},{"key":"dm_box_G","type":"yes_no","sensitive":true,"show_if":{"field":"dm_q9","op":"eq","value":"yes"},"label":{"en":"Box G — Ostomy without swim clearance; dehydration needing care (7 days); stomach ulcers or ulcer surgery (6 mo); frequent heartburn/GERD; active colitis or Crohn’s; bariatric surgery (12 mo)?","es":"Casilla G — Ostomía sin autorización para nadar; deshidratación con atención (7 días); úlceras o cirugía (6 meses); acidez/ERGE frecuente; colitis o Crohn activo; cirugía bariátrica (12 meses)?"}},{"key":"dm_q10","type":"yes_no","required":true,"sensitive":true,"label":{"en":"10. Taking prescription medication (except birth control, or anti-malarials other than mefloquine/Lariam)? (physician if YES)","es":"10. ¿Tomas medicación con receta (excepto anticonceptivos, o antimaláricos distintos de mefloquina/Lariam)? (médico si SÍ)"}}]},{"id":"physician_stub","title":{"en":"Physician section","es":"Sección del médico"},"fields":[{"key":"__physician_blank","type":"checkbox","label":{"en":"(Left blank for physician — shop adds Diving Medical Guidance when needed)","es":"(En blanco para el médico — la tienda añade la Guía Médica si hace falta)"}}]}]}',
 '', 'overlay', '{"placements":[]}','["en","es"]', 2555, NULL, strftime('%s','now')*1000, strftime('%s','now')*1000),

